package com.enterprise.payroll.controller;

import com.enterprise.payroll.service.BonusService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/payroll/departments")
public class PayrollBonusController {

    private final BonusService bonusService;

    public PayrollBonusController(BonusService bonusService) {
        this.bonusService = bonusService;
    }

    @PostMapping("/{deptId}/bonuses/{bonusId}/approve")
    @PreAuthorize("hasRole('DEPARTMENT_MANAGER') and @departmentSecurityService.isManagerOfDept(authentication.name, #deptId)")
    public ResponseEntity<String> approveDiscretionaryBonus(
            @PathVariable String deptId,
            @PathVariable Long bonusId) {
        bonusService.approveBonusAllocation(deptId, bonusId);
        return ResponseEntity.ok("Bonus approved for disbursement");
    }
}
